INSERT INTO "_mocha_migrations" ("number","up_sql","down_sql","applied_at") VALUES(1,replace('-- Zones table\nCREATE TABLE zones (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  slug TEXT NOT NULL,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Tables table\nCREATE TABLE tables (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  zone_id INTEGER NOT NULL,\n  table_number INTEGER NOT NULL,\n  capacity INTEGER NOT NULL DEFAULT 2,\n  status TEXT DEFAULT ''available'',\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX idx_tables_zone ON tables(zone_id);\nCREATE INDEX idx_tables_status ON tables(status);\n\n-- Categories table\nCREATE TABLE categories (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  slug TEXT NOT NULL,\n  icon TEXT,\n  sort_order INTEGER DEFAULT 0,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Products table\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  price REAL NOT NULL,\n  category_id INTEGER,\n  is_available BOOLEAN DEFAULT 1,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX idx_products_category ON products(category_id);\n\n-- Orders table\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  table_id INTEGER,\n  zone_slug TEXT,\n  table_number INTEGER,\n  status TEXT DEFAULT ''open'',\n  subtotal REAL DEFAULT 0,\n  tax REAL DEFAULT 0,\n  total REAL DEFAULT 0,\n  notes TEXT,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX idx_orders_table ON orders(table_id);\nCREATE INDEX idx_orders_status ON orders(status);\n\n-- Order items table\nCREATE TABLE order_items (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  order_id INTEGER NOT NULL,\n  product_id INTEGER,\n  product_name TEXT NOT NULL,\n  quantity INTEGER NOT NULL DEFAULT 1,\n  unit_price REAL NOT NULL,\n  total_price REAL NOT NULL,\n  notes TEXT,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX idx_order_items_order ON order_items(order_id);\n\n-- Seed zones\nINSERT INTO zones (name, slug) VALUES \n  (''Patio Central'', ''patio''),\n  (''Pérgolas'', ''pergolas''),\n  (''VIP'', ''vip'');\n\n-- Seed tables for each zone\nINSERT INTO tables (zone_id, table_number, capacity) VALUES \n  (1, 1, 2), (1, 2, 2), (1, 3, 4), (1, 4, 4), (1, 5, 2), (1, 6, 6),\n  (2, 1, 2), (2, 2, 2), (2, 3, 2), (2, 4, 2), (2, 5, 2), (2, 6, 2), (2, 7, 2), (2, 8, 2),\n  (3, 1, 6), (3, 2, 8), (3, 3, 6), (3, 4, 10);\n\n-- Seed categories\nINSERT INTO categories (name, slug, icon, sort_order) VALUES \n  (''Todos'', ''all'', ''home'', 0),\n  (''Bebidas'', ''bebidas'', ''wine'', 1),\n  (''Cócteles'', ''cocteles'', ''cocktail'', 2),\n  (''Entradas'', ''entradas'', ''utensils'', 3),\n  (''Platos Principales'', ''platos'', ''fish'', 4),\n  (''Postres'', ''postres'', ''cake'', 5);\n\n-- Seed products\nINSERT INTO products (name, price, category_id) VALUES \n  (''Polar Lata 355ml'', 3.50, 2),\n  (''Agua Mineral 355ml'', 2.00, 2),\n  (''Agua Soda SPRK 355ml'', 3.00, 2),\n  (''7UP Lata 355ml'', 3.50, 2),\n  (''Pepsi Lata 355ml'', 3.50, 2),\n  (''Nestea Frappe'', 3.00, 2),\n  (''Jugo Natural (Melón, Lechosa, Piña)'', 3.00, 2),\n  (''Limonada y Parchita'', 5.00, 2),\n  (''Batidos (Melocotón, Fresas)'', 5.00, 2),\n  (''Chelada'', 4.00, 3),\n  (''Caipiriña'', 5.00, 3),\n  (''Mojitos'', 5.00, 3),\n  (''Copa de Verano'', 6.00, 3),\n  (''Aperol Spritz'', 7.00, 3),\n  (''Margarita'', 6.00, 3),\n  (''Daiquiri'', 5.00, 3),\n  (''Cuba Libre'', 5.00, 3),\n  (''Kaipiroca'', 6.00, 3),\n  (''Laguna Beach'', 6.00, 3),\n  (''Mocktail Laguna Fresh'', 6.00, 3),\n  (''Gin Tonic Vodka Importado'', 10.00, 3),\n  (''Gin Tonic Vodka Naciona